// Money and the hard turns of adult life, from the author's direction (26 Oct 2026):
// most lives reach 60 with too little, too late. Effects are authored game design, not
// forecasts. Choosing to invest is real in this game: autoInvest() buys funds every period,
// so the compounding shows up on the balance sheet, not only in the text.
import {experiencedFundLoss,marketFollowup} from './market-evidence.js';
const opt=(id,label,effects,outcome,later=[])=>({id,label,...effects,outcome,later});
const L=(after,effects,text,when)=>({after,...effects,text,when});
const At=(at,effects,text,when)=>({at,...effects,text,when});
const flag=(s,k)=>s.story?.flags?.[k]!==undefined;
const seenAt=(s,id)=>s.story?.seen?.find(e=>e.id===id)?.age??99;
const crashSince=(s,age)=>s.history.some(r=>r.age>age&&(r.economy?.contractions??[]).length>0);
const erosion=[At(60,{},'Your cash balance is nominal. This game does not yet model changes in purchasing power.')];
const working=s=>['work','vocational'].includes(s.pathway??s.history.at(-1)?.pathway);
export const MONEY_LESSONS=[
 {id:'m_runway',category:'money',min:15,max:20,priority:1,stop:true,lesson:'Starting early gives savings more time, but fund returns remain uncertain. Cash for present needs also matters.',title:'What will you live on after 60?',prompt:'Illustration: spending ฿20,000 a month for twenty years totals ฿4.8 million. At an assumed constant 5% annual return, reaching that amount would take about ฿3,100 a month from 20, or ฿11,700 from 40, before fees and inflation. Actual game returns vary. How do you balance future savings and present needs?',options:[
  opt('both','Invest what you save, and buy things that teach you',{skills:{craft:1,iq:1},flag:'invests'},'What you saved went into a fund. Some of the rest bought books and kits.'),
  opt('invest','Invest everything you save, every month',{flag:'invests'},'You opened a small fund account. Everything you saved went in, before anything else.'),
  opt('self','Spend it on things that teach you',{skills:{craft:2,iq:1},flag:'selfInvest'},'You bought books, comics, model kits and Lego. Your room filled with things you had built.'),
  opt('spend','Spend it on now',{wellbeing:2},'You spent it on snacks, outings and whatever everyone else had.',[At(60,{},'Retirement changes the income you can rely on. Your account record shows what you have available.')]) ]},
 {id:'m_kits',category:'study',min:15,max:20,lesson:'What you play with when young can become how you think and what you do for a living.',title:'Lego, comics or a console',prompt:'You have saved enough for one thing: a big box of model kits and Lego, a shelf of comics and novels, or a game console.',options:[
  opt('save','Keep saving instead',{},'You kept the money. The shelf stayed empty for now.'),
  opt('kits','Model kits and Lego',{cash:-2000,skills:{craft:2},flag:'builder'},'You built for months: towers, cars, a whole city on the floor.',[L(15,{cash:30000,wellbeing:2},'The way you learned to build showed up in your work: you could see how things fit together.',s=>(s.skills.craft??0)>=25)]),
  opt('stories','Comics and novels',{cash:-1500,skills:{eq:1,iq:1}},'You read everything. Other people’s lives became easier to imagine.',[L(15,{skills:{eq:1}},'Years of stories made you good at understanding people.')]),
  opt('console','A game console',{cash:-3000,wellbeing:2},'You played late into the night.',[L(10,{cash:25000},'You had started making small games of your own. One of them led to paid work.',s=>(s.skills.craft??0)>=25),L(10,{},'The console years were fun, and that was all they were.',s=>(s.skills.craft??0)<25)]) ]},
 {id:'m_funds',category:'money',min:20,max:35,stop:true,lesson:'Funds can gain or lose value. Cash remains liquid; purchasing-power changes are not yet modeled here.',title:'Where do your savings live?',prompt:'Your savings are in cash. You could keep liquidity, choose the scenario funds, or take a concentrated cryptocurrency bet. The game uses authored outcomes, not forecasts.',eligible:s=>!flag(s,'invests'),options:[
  opt('bank','Keep it all in the bank',{},'You left it where it was. It felt safe.',erosion),
  opt('funds','Spread it across funds, every month',{flag:'invests'},'You split your savings across bond and share funds, and kept adding every month.'),
  opt('crypto','Put it into cryptocurrency',{cash:-20000,flag:'crypto'},'You bought coins. The price moved every hour.',[L(5,{cash:200000,wellbeing:3},'The coin multiplied. You were lucky, and you knew it.',s=>s.seed%4===0),L(5,{wellbeing:-4},'The coin collapsed. The money was gone.',s=>s.seed%4!==0),...erosion]) ]},
 {id:'m_leverage',category:'money',min:30,max:50,stop:true,lesson:'Borrowing to invest turns a normal crash into a total loss. Many families have lost everything this way.',title:'Everyone is borrowing to buy more',prompt:'Prices have only gone up for years. Colleagues borrow against their homes to buy three times more shares and flats. A bank offers you a five-year loan to do the same.',options:[
  opt('no','Invest only what you own',{},'You stayed with what you had. Others got richer, faster, for a while.',[L(10,{wellbeing:2},'A crash came while others were in debt. You lost some value and nothing else.',s=>crashSince(s,seenAt(s,'m_leverage')))]),
  opt('borrow','Borrow and buy three times more',{flag:'leveraged'},'You borrowed against everything and bought more.',[L(10,{cash:-180000,wellbeing:-8,health:-3},'A crash came while the loan was open. The bank called it in. You sold at the bottom and lost more than you had.',s=>crashSince(s,seenAt(s,'m_leverage'))),L(10,{cash:90000},'The five-year loan closed before any crash came. The borrowed bet paid, this time.',s=>!crashSince(s,seenAt(s,'m_leverage')))]) ]},
 {id:'m_crash',category:'money',min:20,max:55,priority:1,stop:true,lesson:'A loss makes liquidity and future market exposure compete. Neither selling nor holding guarantees a better outcome.',title:'Your funds have lost value',prompt:'Your held funds lost value during the last chapter. Keeping them leaves you exposed to further market changes. Selling gives you cash, with fees. Which need matters most now?',eligible:experiencedFundLoss,options:[
  opt('hold','Keep the holdings',{wellbeing:-1},'You kept your holdings. Their value can rise or fall; future contributions still need available money.',[L(5,{},marketFollowup)]),
  opt('sell','Sell the holdings and stop automatic investing',{wellbeing:1,flag:'panicSold',sellAll:true},'You sold your holdings and stopped automatic investing. The actual sale and fees are recorded in your account.',[L(5,{},marketFollowup)]) ]},
 {id:'m_debt',category:'money',min:25,max:65,priority:1,stop:true,lesson:'Debt grows while you decide. Facing it early costs less than facing it late.',title:'The balance keeps growing',prompt:'What you owe has grown past what a year of your income can cover, and interest is added every month. The bank has stopped sending reminders and started sending letters.',eligible:s=>(s.finance?.debt??0)>=500000,options:[
  opt('plan','Sit down with the bank and agree a repayment plan',{wellbeing:-1,skills:{drive:1}},'You wrote down every payment and met the bank each month. It was dull and it was steady.',[L(5,{cash:80000,wellbeing:2},'You kept to the plan. The bank reduced the interest and the balance stopped growing.')]),
  opt('family','Ask the family for help',{cash:200000,wellbeing:-3,flag:'familyLoan'},'Your family covered part of it. Nobody said the number out loud, and nobody forgot it.',[L(10,{wellbeing:-2},'The family loan was never mentioned and never quite settled.')]),
  opt('extra','Take every extra shift you can find',{cash:120000,health:-4,wellbeing:-2},'You worked evenings and weekends. The balance fell, and so did your sleep.',[L(5,{health:-2},'The extra work caught up with your body.',s=>s.health<60)]),
  opt('ignore','Stop opening the letters',{wellbeing:-4},'You put the letters in a drawer. The drawer filled.',[L(5,{cash:-100000,wellbeing:-4},'The interest kept running while you looked away. The bank added fees and a collector called.')]) ]},
 {id:'m_house',category:'money',min:30,max:45,stop:true,lesson:'Owning a home is not always better than renting; what matters is whether the difference is saved and invested.',title:'Buy a home or keep renting?',prompt:'A bank will lend you most of the price of a home for thirty years. Renting costs less each month, and you can move.',options:[
  opt('rent','Keep renting and invest the difference',{flag:'invests'},'You kept renting and put what a deposit would have cost into funds, every month.'),
  opt('buy','Buy with a thirty-year loan',{cash:-60000,flag:'owner'},'You paid the deposit and signed for thirty years.',[L(10,{cash:-40000},'Repairs, taxes and interest. Owning cost more than the brochure said.'),At(60,{cash:250000,wellbeing:2},'The loan was nearly paid. You owned the roof over your head.')]) ]},
 {id:'m_offer',category:'work',min:25,max:45,stop:true,lesson:'An interesting risk taken while you can still recover is worth more than one taken when you cannot.',title:'An interesting offer, half the pay',prompt:'A small team is building something you care about. They offer you half your pay and a share of the company, if it ever works.',eligible:working,options:[
  opt('stay','Stay in your steady job',{},'You stayed. The salary kept coming.',[L(10,{wellbeing:-1},'Sometimes you looked up what that team became.')]),
  opt('join','Join them',{cash:-20000,wellbeing:3,skills:{drive:1,craft:1},flag:'joinedRisk'},'You joined. The work was the most alive you had felt.',[L(10,{cash:250000,wellbeing:3},'It worked. Your share was worth years of salary.',s=>s.seed%4===0),L(10,{cash:-20000,skills:{iq:1}},'It failed. You went back to a steady job, knowing far more than before.',s=>s.seed%4!==0)]) ]},
 {id:'m_insure',category:'money',min:25,max:40,lesson:'Insurance feels wasted every year that nothing happens. It exists for the one year that does.',title:'Insure against the worst?',prompt:'A policy would cover fire, accident and serious illness. It costs a little every month, for something that may never happen.',options:[
  opt('skip','Skip it',{},'You kept the money.',[L(10,{cash:-90000,health:-4,wellbeing:-4},'An accident and a fire in the same year. With no cover, every baht came from you.',s=>s.seed%3===0),L(10,{cash:10000},'Nothing happened. You kept the premiums.',s=>s.seed%3!==0)]),
  opt('insure','Take the cover',{cash:-6000,flag:'insured'},'You signed and forgot about it.',[L(10,{cash:-6000,wellbeing:2},'An accident and a fire in the same year. The insurer paid for most of it.',s=>s.seed%3===0),L(10,{cash:-8000},'Nothing happened. The premiums were the cost of sleeping well.',s=>s.seed%3!==0)]) ]},
 {id:'m_vanished',category:'connection',min:25,max:55,lesson:'Lend only what you could afford to give. Money between friends can take the friend with it.',title:'An old friend needs money',prompt:'An old friend calls about an emergency and asks to borrow ฿50,000. They promise to pay it back in six months.',options:[
  opt('no','Say you cannot',{wellbeing:-1},'You said no. They went quiet.'),
  opt('gift','Give a smaller amount, as a gift',{cash:-10000,wellbeing:1},'You gave what you could afford to lose and said it was not a loan.',[L(5,{wellbeing:2},'The friendship stayed. No debt sat between you.')]),
  opt('lend','Lend the full amount',{cash:-50000},'You transferred the money. They thanked you, close to tears.',[L(5,{wellbeing:-5},'They stopped answering. The money and the friend disappeared together.',s=>s.seed%2===0),L(5,{cash:50000,wellbeing:2},'They paid it back, late but in full.',s=>s.seed%2===1)]) ]},
 {id:'m_unfair',category:'work',min:30,max:55,lesson:'Doing everything right does not make things go right. What you control is the next move.',title:'You did everything right',prompt:'You worked hard and did good work for years. The promotion went to someone else, for reasons that had nothing to do with work.',eligible:working,options:[
  opt('next','Accept it, and plan your next move',{skills:{eq:1}},'It stung. You started quietly preparing for what came next.',[L(5,{wellbeing:3},'The next door you opened was better than the one that closed.')]),
  opt('bitter','Stay, and let it eat at you',{wellbeing:-3},'You stayed and replayed it every night.',[L(5,{health:-3,wellbeing:-3},'The resentment outlasted the job.')]),
  opt('leave','Leave at once',{cash:-20000,wellbeing:1},'You resigned the same month.') ]},
 {id:'m_flat',category:'health',min:40,max:55,stop:true,lesson:'When adult life stops being fun, small new practices usually help more than burning everything down.',title:'Life is no longer fun',prompt:'Work, bills, the same week again. Nothing is wrong, exactly. Nothing feels like anything any more.',options:[
  opt('endure','Carry on; this is adulthood',{wellbeing:-2},'You carried on.',[L(5,{wellbeing:-3,health:-2},'The greyness did not lift on its own.')]),
  opt('small','Start one small new thing each week',{cash:-3000,skills:{physique:1,craft:1}},'A class, a sport, a long walk somewhere new. Small, every week.',[L(5,{wellbeing:5,health:2},'The weeks had texture again.')]),
  opt('talk','Talk to someone about it',{cash:-5000,skills:{eq:1}},'You told a counsellor, and then a friend, the truth.',[L(5,{wellbeing:4},'Naming it made it smaller.')]),
  opt('burn','Quit everything and start over',{cash:-60000,wellbeing:3},'You quit, sold things and left.',[L(5,{wellbeing:4},'Starting over was hard and it was yours.',s=>s.seed%2===0),L(5,{cash:-30000,wellbeing:-5},'The same greyness followed you to the new place.',s=>s.seed%2===1)]) ]},
 {id:'m_grandparent',category:'family',min:25,max:25,priority:1,lesson:'The people who raised your parents carry the family’s memory. Ask them while you can.',title:'A grandparent dies',prompt:'Your grandparent has died after a short illness. There is a funeral to arrange and stories no one wrote down.',eligible:s=>s.seed%2===0,options:[
  opt('stay','Attend the rites, then go back to work',{wellbeing:-2},'You helped with the rites and went back to work a week later.'),
  opt('stories','Help, and record the family’s stories',{cash:-3000,wellbeing:-1,skills:{eq:1}},'You sat with the elders and wrote down what they remembered.',[L(15,{wellbeing:3},'The stories you kept became your children’s and cousins’ history.')]) ]},
 {id:'m_pet',category:'family',min:35,max:75,priority:1,lesson:'Grief for an animal is real grief. It measures how much ordinary days were shared.',title:'Your dog is dying',prompt:'Your dog is old and in pain. The vet says it is time.',eligible:s=>{const d=s.story?.flags?.dog;return d!==undefined&&s.age-d===10;},options:[
  opt('stay','Stay with them to the end',{wellbeing:-3,flag:'dogDied'},'You held your dog while the vet worked. The house was very quiet after.',[L(5,{wellbeing:2},'Walks still started at the old time, out of habit. It made you smile.')]),
  opt('treat','Pay for treatment to buy more time',{cash:-25000,wellbeing:-2,flag:'dogDied'},'You paid for treatment. Some good weeks came, then the end.') ]},
 {id:'m_child',category:'family',min:40,max:60,priority:1,stop:true,lesson:'No one is prepared for the death of a child. Grief shared, and help taken, is what carries people through.',title:'Your child has died',prompt:'Your child has died in an accident. Nothing makes sense. If you or someone close to you feels unsafe, please reach someone you trust today. In Thailand, the mental health hotline is 1323.',eligible:s=>flag(s,'parent')&&s.age-s.story.flags.parent>=5&&s.seed%13===0,options:[
  opt('together','Grieve together, with help',{wellbeing:-6,flag:'childLost'},'You and your family held on to each other and joined a free support group.',[L(5,{wellbeing:5},'The grief did not leave. It became something you could carry.')]),
  opt('work','Go back to work and keep busy',{wellbeing:-6,flag:'childLost'},'You went back to work within the week.',[L(5,{health:-5,wellbeing:-4},'The grief waited for you, and arrived all at once.')]),
  opt('withdraw','Withdraw from everyone',{wellbeing:-8,flag:'childLost'},'You stopped seeing people.',[L(5,{wellbeing:-4},'The silence grew. Slowly, someone kept knocking.')]) ]},
 {id:'m_passive',category:'money',min:45,max:55,stop:true,lesson:'Salary stops; what earns without you does not. Build it before 60, or keep working at 65 and 70.',title:'Income that does not need you',prompt:'In fifteen years your salary will stop. You could build a private practice, buy a small place to rent out, or keep your salary and hope.',options:[
  opt('salary','Keep the salary and hope',{},'You kept going as before.',[At(65,{health:-2,wellbeing:-3},'At 65 you were still working, because you had to.',s=>!flag(s,'invests')),At(65,{wellbeing:1},'Your funds covered the years after 60. You could stop.',s=>flag(s,'invests'))]),
  opt('practice','Build a private practice on the side',{cash:-30000,health:-2,skills:{craft:1,eq:1},flag:'practice'},'Evenings and weekends went into a practice of your own.',[At(60,{cash:180000,wellbeing:3},'Clients came to you now, not to your employer.'),At(70,{cash:120000},'The practice still paid, on fewer days.')]),
  opt('rental','Buy a small place to rent out',{cash:-80000,flag:'landlord'},'You bought a small unit and found a tenant.',[L(10,{cash:-20000},'Repairs and an empty year.'),At(65,{cash:200000},'The rent came in every month, whether you worked or not.')]) ]}
];
